-- the logger (VRFW_Log), made at the first line: the framework's menu files load after the graft blocks
function BBT_Logger()
  BattleBayDeluxe.Tournament.logger = BattleBayDeluxe.Tournament.logger or VRFW_Log.New("BattleBayDeluxe.tournament")
